// pdb: RepairMenu::Update | RepairMenu.obj | fnv360_0822_retail, ustr, medium
void RepairMenu::FUN_00672a20()
{
    if (!pBrokenItem)
        return;
    SimpleList<ItemChange*> pnewItemGroup;
    InventoryChanges* pinventory = GetInventoryChanges(g_thePlayer);
    pinventory->Collect(pBrokenItem->GetContainerObj(), &pnewItemGroup);
    for (SimpleList<ItemChange*>* pcurrItemObj = &pnewItemGroup; pcurrItemObj && pcurrItemObj->GetItem();
         pcurrItemObj = pcurrItemObj->GetNext()) {
        ItemChange* pnewItem = 0;
        Tile* pnewTile = 0;
        for (int iitemCt = 0; iitemCt < pcurrItemObj->GetItem()->GetCount(); ++iitemCt) {
            float fcondition = pcurrItemObj->GetItem()->GetHealth(true);
            if (fcondition < 100.0 || pcurrItemObj->GetItem()->GetContainerObj() != pBrokenItem->GetContainerObj()) {
                if (!iitemCt) {
                    pnewItem = pcurrItemObj->GetItem();
                    pnewTile = pMe->lbRepairList.AddItem(pnewItem, pnewItem->GetName(0, 0));
                    if (pnewItem->GetContainerObj() == pBrokenItem->GetContainerObj() &&
                        pnewItem->GetFirstExtra() == pBrokenItem->GetFirstExtra()) {
                        pBrokenItem = pnewItem;
                        pnewTile->SetFloat(iUT_IsRepairItem, 1.0f, true);
                        TileValue* pheight = pMe->pTiles[2]->GetValue(0xfb0);
                        TileValue* py = pMe->pTiles[2]->GetValue(0xfa2);
                        pheight->Clear();
                        pheight->Link(0x7d0, pnewTile, 0xfb0);
                        pheight->SetNumber(0x7d2, 1.0f);
                        pheight->Finish(0);
                        py->Clear();
                        py->Link(0x7d0, pnewTile, 0xfa2);
                        py->Finish(0);
                    }
                } else {
                    pnewItem = new ItemChange(pcurrItemObj->GetItem()->GetContainerObj(), 1);
                    for (SimpleList<ExtraDataList*>* pcurrExtraObj = pcurrItemObj->GetItem()->pExtraObjectList;
                         pcurrExtraObj && pcurrExtraObj->GetItem(); pcurrExtraObj = pcurrExtraObj->GetNext())
                        pnewItem->pExtraObjectList->AddHead(pcurrExtraObj->GetItem());
                    pMe->lbRepairList.AddItem(pnewItem, pnewItem->GetName(0, 0));
                }
            }
        }
    }
    if (strcmp(g_sLanguage, "ENGLISH")) {
        pMe->GetMenuTile()->GetChild("RM_Headline_Title")->SetString(0xfc4, g_sRepairTitle.String(), true);
        pMe->pTiles[0]->SetString(iUT_Value, g_sRepairItemTitle.String(), true);
        pMe->pTiles[4]->SetString(iUT_Value, g_sRepairValue.String(), true);
        pMe->pTiles[9]->SetString(iUT_Value, g_sRepairValue.String(), true);
        pMe->pTiles[11]->SetString(0xfc4, g_sRepairHint1.String(), true);
        pMe->pTiles[12]->SetString(0xfc4, g_sRepairHint2.String(), true);
    }
}

